-- VYRA · szablony siłowni z planu 2026/27: Siłownia A (nogi i siła) i Siłownia B (plyo i stabilizacja).
-- Uruchom raz w Supabase → SQL Editor. Ponowne uruchomienie nie dubluje szablonów.
do $$
declare v_coach uuid;
begin
  select id into v_coach from public.profiles
   where role = 'coach' and lower(trim(full_name)) = lower('Kacper Adamczyk')
   order by (staff_role = 'founder') desc, created_at limit 1;
  if v_coach is null then
    select id into v_coach from public.profiles where role = 'coach' and staff_role = 'founder' order by created_at limit 1;
  end if;
  if v_coach is null then raise exception 'Nie znaleziono konta trenera.'; end if;
  insert into public.training_templates (coach_id, name, description, kind, category, payload)
  select v_coach, 'Siłownia A: nogi i siła', 'Wtorek po akcencie, 40-45 min. Serie i powtórzenia dopasuj do fazy planu.', 'strength', 'strength', '{"kind": "strength", "category": "strength", "title": "Siłownia A: nogi i siła", "goal": "Siła nóg, ekonomia biegu i odporność na kontuzje", "instructions": "Wtorek po akcencie (najlepiej po południu, min. 3 godziny po biegu), 40-45 min.\nRozgrzewka: 8-10 min roweru lub marszu, aktywacja pośladków (mostek, monster walk), 2 serie rozgrzewkowe.\nZapas 2-3 powtórzeń, nigdy do upadku. Technika ważniejsza od ciężaru.\nProgresja: paź 2×10-12 lekko · lis 3×8 · gru-sty 4×4-5 ciężko · sty-lut 3×4 · lut-kwi 3×3-4 · maj 3×5-6.", "planned_duration_s": 2700, "exercises": [{"name": "Przysiad ze sztangą lub trap-bar deadlift", "description": null, "muscle_group": "nogi", "rest_s": 150, "tempo": null, "notes": "4×4-5, pełna kontrola, bez „pompowania” tempa", "sets": [{"planned_reps": 5, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 5, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 5, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 5, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Martwy ciąg rumuński", "description": null, "muscle_group": "tył uda", "rest_s": 120, "tempo": null, "notes": "Plecy neutralnie", "sets": [{"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Przysiad bułgarski", "description": null, "muscle_group": "nogi", "rest_s": 90, "tempo": null, "notes": "6 na nogę, stabilizacja miednicy", "sets": [{"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 6, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Hip thrust", "description": null, "muscle_group": "pośladki", "rest_s": 90, "tempo": null, "notes": "Pośladki to silnik biegacza", "sets": [{"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Łydki stojąc i siedząc (wolny ekscentryk)", "description": null, "muscle_group": "łydki", "rest_s": 60, "tempo": null, "notes": "10-12, ochrona ścięgna Achillesa", "sets": [{"planned_reps": 12, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 12, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 12, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Core: plank boczny, dead bug, Pallof press", "description": null, "muscle_group": "core", "rest_s": 45, "tempo": null, "notes": "30-40 s, stabilizacja tułowia", "sets": [{"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 35, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 35, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 35, "planned_rpe": null, "planned_rir": null}]}]}'::jsonb
  where not exists (select 1 from public.training_templates where coach_id = v_coach and name = 'Siłownia A: nogi i siła');

  insert into public.training_templates (coach_id, name, description, kind, category, payload)
  select v_coach, 'Siłownia B: plyo i stabilizacja', 'Czwartek, 30-35 min, przed sprintami. Plyo w małej objętości.', 'strength', 'power', '{"kind": "strength", "category": "power", "title": "Siłownia B: plyo i stabilizacja", "goal": "Sprężystość, krótki kontakt z podłożem, stabilizacja bioder i kostki", "instructions": "Czwartek, 30-35 min. Plyo na świeżych nogach, przed sprintami, w małej objętości. Stabilizacja i core po bieganiu.\nRozgrzewka: 8-10 min roweru lub marszu, aktywacja pośladków.\nW tygodniu startowym tylko core i stabilizacja.", "planned_duration_s": 2000, "exercises": [{"name": "Skoki: skip A/B, pogo, skoki na skrzynię 30-40 cm", "description": null, "muscle_group": "plyo", "rest_s": 90, "tempo": null, "notes": "8-10 (20-30 kontaktów), krótki kontakt, zawsze przed sprintami", "sets": [{"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}]}, {"name": "Bounding / skoki jednonóż", "description": null, "muscle_group": "plyo", "rest_s": 90, "tempo": null, "notes": "3×20-30 m. W fazach B i C, w kwietniu tylko lekko", "sets": [{"planned_reps": null, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}]}, {"name": "Single-leg RDL", "description": null, "muscle_group": "tył uda", "rest_s": 60, "tempo": null, "notes": "Równowaga i ścięgna podkolanowe", "sets": [{"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Step-up na skrzynię", "description": null, "muscle_group": "nogi", "rest_s": 60, "tempo": null, "notes": "Siła pojedynczej nogi", "sets": [{"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}, {"planned_reps": 8, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": 2}]}, {"name": "Copenhagen plank, monster walk z gumą", "description": null, "muscle_group": "biodra", "rest_s": 45, "tempo": null, "notes": "20-30 s, biodra i pachwiny", "sets": [{"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 25, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 25, "planned_rpe": null, "planned_rir": null}, {"planned_reps": null, "planned_load_kg": null, "planned_duration_s": 25, "planned_rpe": null, "planned_rir": null}]}, {"name": "Mostek jednonóż, ćwiczenia kostki (wspięcia, balans)", "description": null, "muscle_group": "kostka", "rest_s": 45, "tempo": null, "notes": "Kostka i stopa przy terenie", "sets": [{"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}, {"planned_reps": 10, "planned_load_kg": null, "planned_duration_s": null, "planned_rpe": null, "planned_rir": null}]}]}'::jsonb
  where not exists (select 1 from public.training_templates where coach_id = v_coach and name = 'Siłownia B: plyo i stabilizacja');

  raise notice 'Szablony siłowni gotowe.';
end $$;
